四、手写左闭右开(推荐写法)
升序
int lower_bound(int q[], int l, int r, int x) {
 while (l < r) {
 int mid = (l + r) / 2;
 if (q[mid] >= x)
 r = mid;
 else
 l = mid + 1;
 }
 return l;
}
int upper_bound(int q[], int l, int r, int x) {
 while (l < r) {
 int mid = (l + r) / 2;
 if (q[mid] > x)
 r = mid;
 else
 l = mid + 1;
 }
 return l;
}
